                Id = 2, Title = "Avocado Toast", Category = "Breakfast", ImageEmoji = "🥑",
                Ingredients = new() { "2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice" },
                Steps = new() { "Toast the bread until golden.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado on toast.", "Sprinkle with red pepper flakes." },
                Ratings = new() { 4, 5 }
            },
            new Recipe
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch", ImageEmoji = "🥗",
                Ingredients = new() { "1 head romaine lettuce", "Caesar dressing", "Croutons", "Parmesan cheese", "Grilled chicken breast" },
                Steps = new() { "Wash and chop the lettuce.", "Grill and slice the chicken.", "Toss lettuce with dressing.", "Top with croutons, parmesan, and chicken." },
                Ratings = new() { 4, 4, 3 }
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Bolognese", Category = "Dinner", ImageEmoji = "🍝",
                Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400ml tomato sauce", "Italian herbs", "Parmesan cheese" },
                Steps = new() { "Cook spaghetti according to package directions.", "Sauté onion and garlic until soft.", "Brown the ground beef.", "Add tomato sauce and herbs, simmer 20 minutes.", "Serve sauce over spaghetti with parmesan." },
                Ratings = new() { 5, 5, 4, 5 }
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", ImageEmoji = "🍫",
                Ingredients = new() { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "50g sugar", "1 tbsp flour" },
                Steps = new() { "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold chocolate mixture into eggs, then add flour.", "Pour into greased ramekins.", "Bake at 220°C for 12 minutes.", "Invert onto plates and serve immediately." },
                Ratings = new() { 5, 5, 5 }
            },
            new Recipe
            {
                Id = 6, Title = "Trail Mix", Category = "Snacks", ImageEmoji = "🥜",
                Ingredients = new() { "1 cup almonds", "1 cup cashews", "1/2 cup dried cranberries", "1/2 cup chocolate chips", "1/2 cup sunflower seeds" },
                Steps = new() { "Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container." },
                Ratings = new() { 4, 3 }
            },
            new Recipe
            {
                Id = 7, Title = "Iced Matcha Latte", Category = "Beverages", ImageEmoji = "🍵",
                Ingredients = new() { "2 tsp matcha powder", "2 tbsp hot water", "1 cup milk", "Ice cubes", "Sweetener to taste" },
                Steps = new() { "Sift matcha powder into a cup.", "Add hot water and whisk until smooth.", "Fill a glass with ice.", "Pour milk over ice, then add matcha.", "Stir and enjoy." },
                Ratings = new() { 5, 4, 4 }
            },
            new Recipe
            {
                Id = 8, Title = "Grilled Cheese Sandwich", Category = "Lunch", ImageEmoji = "🧀",
                Ingredients = new() { "2 slices bread", "2 slices cheddar cheese", "1 tbsp butter" },
                Steps = new() { "Butter one side of each bread slice.", "Place cheese between bread slices, butter side out.", "Cook in a skillet over medium heat.", "Flip when golden brown, cook other side.", "Slice and serve hot." },
                Ratings = new() { 5, 4, 5, 4 }
            }
        };
        _nextId = 9;
    }

    public List<string> GetCategories() => Categories;

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetRecipeById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public Recipe AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }

    public void AddRating(int recipeId, int rating)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe != null && rating >= 1 && rating <= 5)
            {
                recipe.Ratings.Add(rating);
            }
        }
    }
}

