<PageTitle>@(Category != null ? $"{Category} Recipes" : "Browse Recipes") — RecipeHub</PageTitle>

@if (string.IsNullOrEmpty(Category))
{
    <h1>Browse Recipes</h1>
    <p>Select a category to explore recipes:</p>
    <div class="list-group">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <a href="/recipes/@cat" class="list-group-item list-group-item-action">@cat</a>
        }
    </div>
}
else
{
    <h1>@Category Recipes</h1>
    <a href="/recipes" class="btn btn-outline-secondary mb-3">&larr; All Categories</a>

    var recipes = RecipeService.GetRecipesByCategory(Category);

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category yet.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-4 mb-4">
                    <div class="card recipe-card h-100">
                        <div class="card-body text-center">
                            <div class="recipe-emoji">@recipe.ImageEmoji</div>
                            <h5 class="card-title">@recipe.Title</h5>
                            @if (recipe.Ratings.Count > 0)
                            {
                                <p class="text-muted">⭐ @recipe.Ratings.Average().ToString("F1") (@recipe.Ratings.Count ratings)</p>
                            }
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

