    }
    else
    {
        @for (int i = 1; i <= 5; i++)
        {
            var starValue = i;
            <span class="star @(starValue <= (hoverValue > 0 ? hoverValue : 0) ? "star-filled" : "")"
                  @onmouseover="() => OnHover(starValue)"
                  @onmouseout="OnMouseOut"
