+@rendermode InteractiveServer
+@inject RecipeService RecipeService
+
+<div class="star-rating">
+    @if (submitted)
+    {
+        <p class="text-success fw-bold">Thanks for rating!</p>
+    }
+    else
+    {
+        @for (int i = 1; i <= 5; i++)
+        {
+            var starValue = i;
+            <span class="star @(starValue <= (hoverValue > 0 ? hoverValue : 0) ? "star-filled" : "")"
+                  @onmouseover="() => OnHover(starValue)"
+                  @onmouseout="OnMouseOut"
+                  @onclick="() => SubmitRating(starValue)">
+                @(starValue <= (hoverValue > 0 ? hoverValue : 0) ? "★" : "☆")
+            </span>
+        }
+    }
+</div>
+
+@code {
+    [Parameter]
+    public int RecipeId { get; set; }
+
+    private int hoverValue;
+    private bool submitted;
+
+    private void OnHover(int value)
+    {
+        hoverValue = value;
+    }
+
+    private void OnMouseOut()
+    {
+        hoverValue = 0;
+    }
+
+    private void SubmitRating(int rating)
+    {
+        RecipeService.AddRating(RecipeId, rating);
+        submitted = true;
+    }
+}
+

