@@ -1,66 +1,66 @@
 @page "/recipe/{Id:int}"
 @inject RecipeService RecipeService

 @if (recipe == null)
 {
     <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
     <h1>Recipe Not Found</h1>
     <p>Sorry, we couldn't find that recipe.</p>
     <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
 }
 else
 {
     <PageTitle>@recipe.Title — RecipeHub</PageTitle>

     <a href="/recipes/@recipe.Category" class="btn btn-outline-secondary mb-3">&larr; Back to @recipe.Category</a>

     <div class="recipe-emoji text-center">@recipe.ImageEmoji</div>
     <h1 class="text-center">@recipe.Title</h1>
     <p class="text-center"><span class="badge bg-secondary">@recipe.Category</span></p>

     @if (recipe.Ratings.Count > 0)
     {
         <p class="text-center text-muted">⭐ Average Rating: @recipe.Ratings.Average().ToString("F1") / 5 (@recipe.Ratings.Count ratings)</p>
     }

     <hr />

     <div class="row">
         <div class="col-md-5">
             <h3>Ingredients</h3>
             <ul class="list-group mb-4">
                 @foreach (var ingredient in recipe.Ingredients)
                 {
                     <li class="list-group-item">@ingredient</li>
                 }
             </ul>
         </div>
         <div class="col-md-7">
             <h3>Steps</h3>
             <ol class="list-group list-group-numbered mb-4">
                 @foreach (var step in recipe.Steps)
                 {
                     <li class="list-group-item">@step</li>
                 }
             </ol>
         </div>
     </div>

     <hr />

     <h3>Rate this Recipe</h3>
     <StarRating RecipeId="recipe.Id" />
 }

 @code {
     [Parameter]
     public int Id { get; set; }

     private Recipe? recipe;

     protected override void OnInitialized()
     {
         recipe = RecipeService.GetRecipeById(Id);
     }
 }

